#!/usr/bin/env python3
"""Read-only selection of reproducible Microsoft sample entity anchors."""
import json,pathlib,sqlite3
ROOT=pathlib.Path(__file__).resolve().parents[1]
d=sqlite3.connect(f'file:{ROOT}/data/adventureworks.sqlite?mode=ro',uri=True);d.row_factory=sqlite3.Row
def rows(q,args=()):return [dict(x) for x in d.execute(q,args)]
a={'role':'exploratory source candidate; final presentation anchors are metadata/demo_context.json','source':'Microsoft synthetic AdventureWorks sample; no real enterprise identities','date':'2026-11-16','sales_date_window':rows('SELECT MIN(OrderDate) first_order,MAX(OrderDate) last_order FROM Sales_SalesOrderHeader')[0],'hero_customer':rows('SELECT c.*,s.Name FROM Sales_Customer c JOIN Sales_Store s ON s.BusinessEntityID=c.StoreID WHERE c.CustomerID=29705')[0],'secondary_customer':rows('SELECT c.*,s.Name FROM Sales_Customer c JOIN Sales_Store s ON s.BusinessEntityID=c.StoreID WHERE c.CustomerID=29722')[0],'product':rows('SELECT * FROM Production_Product WHERE ProductID=712')[0],'product_vendor':rows('SELECT pv.*,v.Name vendor_name,v.AccountNumber vendor_account FROM Purchasing_ProductVendor pv JOIN Purchasing_Vendor v ON v.BusinessEntityID=pv.BusinessEntityID WHERE pv.ProductID=712')[0],'hero_orders':rows('SELECT h.SalesOrderID,h.OrderDate,h.DueDate,h.ShipDate,l.SalesOrderDetailID,l.ProductID,l.OrderQty,l.UnitPrice,l.LineTotal FROM Sales_SalesOrderHeader h JOIN Sales_SalesOrderDetail l ON l.SalesOrderID=h.SalesOrderID WHERE h.CustomerID=29705 AND l.ProductID=712 ORDER BY h.OrderDate'),'quantity_by_customer':rows('SELECT h.CustomerID,COUNT(*) order_lines,SUM(l.OrderQty) ordered_quantity FROM Sales_SalesOrderHeader h JOIN Sales_SalesOrderDetail l ON l.SalesOrderID=h.SalesOrderID WHERE h.CustomerID IN (29705,29722) AND l.ProductID=712 GROUP BY h.CustomerID'),'2024_hero_quantity':rows("SELECT SUM(l.OrderQty) ordered_quantity FROM Sales_SalesOrderHeader h JOIN Sales_SalesOrderDetail l ON l.SalesOrderID=h.SalesOrderID WHERE h.CustomerID=29705 AND l.ProductID=712 AND h.OrderDate>='2024-01-01' AND h.OrderDate<'2025-01-01'")[0]}
(ROOT/'metadata/source_candidate_anchors.json').write_text(json.dumps(a,indent=2)+'\n');print(json.dumps(a['quantity_by_customer']))
